  s += starLayer(q + u_parallax * 0.010, 60.0, 0.06, px, t * 1.3, 17.0) * 0.55;
  s += starLayer(q + u_parallax * 0.018, 130.0, 0.07, px, t * 1.7, 41.0) * 0.3;
